(269,59,NULL,'VTS for the Port of Tyne','CREATE',NULL,'{\"id\":59,\"projectNumber\":null,\"name\":\"VTS for the Port of Tyne\",\"awardDate\":\"2022-10-01T00:00:00.000Z\",\"implementationPrice\":1021015,\"maintenancePricePerYear\":0,\"currencyId\":3,\"scope\":\"The Vessel Traffic Service System project aimed to develop and implement a robust software and hardware solution to enhance maritime safety and efficiency in managing vessel traffic within the Port of Tyne VTS and Statutory Harbour Authority Areas. The system was designed to monitor vessel movements, provide real-time information to operators, support decision-making, and facilitate effective communication between vessels and the Tyne Vessel Traffic Service Centre.\",\"projectType\":\"VTS\",\"products\":\"MaritimeControl\",\"description\":null,\"customerDetails\":null,\"endUserDetails\":null,\"countryId\":235,\"systemUnlocodeId\":139,\"pocName\":null,\"pocEmail\":null,\"pocPhone\":null,\"newDevelopments\":null,\"implementationDetails\":null,\"pipedriveNumber\":null,\"pipedriveUrl\":null,\"projectUrl\":null,\"isSensitive\":false,\"canBeUsedAsReference\":true,\"showOnMap\":true,\"systemDecommissioned\":false,\"deleted\":false,\"createdAt\":\"2026-09-09T20:42:34.292Z\",\"updatedAt\":\"2026-09-09T20:42:34.292Z\",\"currency\":{\"id\":3,\"code\":\"GBP\",\"name\":\"Pound Sterling\",\"symbol\":\"£\"},\"country\":{\"id\":235,\"isoCode\":\"GB\",\"name\":\"United Kingdom\"},\"systemUnlocode\":{\"id\":139,\"code\":\"GBTYN\",\"name\":\"Tyne\",\"countryId\":235,\"latitude\":55,\"longitude\":-1.4333,\"country\":{\"id\":235,\"isoCode\":\"GB\",\"name\":\"United Kingdom\"}},\"completionDates\":[],\"ports\":[],\"modules\":[],\"subSystems\":[],\"externalInterfaces\":[],\"people\":[],\"documents\":[]}',NULL,1,'dev@tidalis.com','local user','2026-09-09 20:42:34.304'),
