(276,66,NULL,'VTS for the Port of Klaipeda, Lithuania','CREATE',NULL,'{\"id\":66,\"projectNumber\":null,\"name\":\"VTS for the Port of Klaipeda, Lithuania\",\"awardDate\":\"2015-05-01T00:00:00.000Z\",\"implementationPrice\":1600133,\"maintenancePricePerYear\":0,\"currencyId\":1,\"scope\":\"Klaipeda State Seaport operates 24/7 and is the most northern ice–free port on the Eastern coast of the Baltic Sea. It is the most important and biggest Lithuanian transport hub, connecting sea, land and railway routes from East to West.\\nKlaipeda is a multipurpose, universal, deep-water port, providing high quality services. The annual port cargo handling capacity is up to 60 million tons.\",\"projectType\":\"VTS\",\"products\":\"MaritimeControl\",\"description\":null,\"customerDetails\":null,\"endUserDetails\":null,\"countryId\":130,\"systemUnlocodeId\":144,\"pocName\":null,\"pocEmail\":null,\"pocPhone\":null,\"newDevelopments\":null,\"implementationDetails\":null,\"pipedriveNumber\":null,\"pipedriveUrl\":null,\"projectUrl\":null,\"isSensitive\":false,\"canBeUsedAsReference\":true,\"showOnMap\":true,\"systemDecommissioned\":false,\"deleted\":false,\"createdAt\":\"2026-09-09T20:42:34.469Z\",\"updatedAt\":\"2026-09-09T20:42:34.469Z\",\"currency\":{\"id\":1,\"code\":\"EUR\",\"name\":\"Euro\",\"symbol\":\"€\"},\"country\":{\"id\":130,\"isoCode\":\"LT\",\"name\":\"Lithuania\"},\"systemUnlocode\":{\"id\":144,\"code\":\"LTKLJ\",\"name\":\"Klaipeda\",\"countryId\":130,\"latitude\":55.7167,\"longitude\":21.15,\"country\":{\"id\":130,\"isoCode\":\"LT\",\"name\":\"Lithuania\"}},\"completionDates\":[],\"ports\":[],\"modules\":[],\"subSystems\":[],\"externalInterfaces\":[],\"people\":[],\"documents\":[]}',NULL,1,'dev@tidalis.com','local user','2026-09-09 20:42:34.481'),
(277,67,NULL,'Expansion of SRK VTS Simulator, the Netherlands','CREATE',NULL,'{\"id\":67,\"projectNumber\":null,\"name\":\"Expansion of SRK VTS Simulator, the Netherlands\",\"awardDate\":\"2020-04-01T00:00:00.000Z\",\"implementationPrice\":109000,\"maintenancePricePerYear\":0,\"currencyId\":1,\"scope\":\"The VTS Simulator has a flexible set-up. Trainings can be set-up with any number of instructors/ship operators and any number of trainees. The simulator has been designed in such a way that it can use the same charts as the operational VTS. Recorded traffic situations (e.g. incidents) can be imported into the simulator to serve as the starting point of a training.\\nIn general this next level VTS Simulator shares the same technology and traffic display as the operational VTS. Furthermore, it has a very efficient user interface to optimize the development of training scenarios.\",\"projectType\":\"VTS\",\"products\":\"TactiCall\",\"description\":null,\"customerDetails\":null,\"endUserDetails\":null,\"countryId\":22,\"systemUnlocodeId\":4,\"pocName\":null,\"pocEmail\":null,\"pocPhone\":null,\"newDevelopments\":null,\"implementationDetails\":null,\"pipedriveNumber\":null,\"pipedriveUrl\":null,\"projectUrl\":null,\"isSensitive\":false,\"canBeUsedAsReference\":true,\"showOnMap\":true,\"systemDecommissioned\":false,\"deleted\":false,\"createdAt\":\"2026-09-09T20:42:34.491Z\",\"updatedAt\":\"2026-09-09T20:42:34.491Z\",\"currency\":{\"id\":1,\"code\":\"EUR\",\"name\":\"Euro\",\"symbol\":\"€\"},\"country\":{\"id\":22,\"isoCode\":\"BE\",\"name\":\"Belgium\"},\"systemUnlocode\":{\"id\":4,\"code\":\"BEANR\",\"name\":\"Antwerpen\",\"countryId\":22,\"latitude\":51.2194,\"longitude\":4.4025,\"country\":{\"id\":22,\"isoCode\":\"BE\",\"name\":\"Belgium\"}},\"completionDates\":[],\"ports\":[],\"modules\":[],\"subSystems\":[],\"externalInterfaces\":[],\"people\":[],\"documents\":[]}',NULL,1,'dev@tidalis.com','local user','2026-09-09 20:42:34.504'),
