(284,74,NULL,'Chittagong Upgrade and Extension (Lot 1 & Lot 2)','CREATE',NULL,'{\"id\":74,\"projectNumber\":null,\"name\":\"Chittagong Upgrade and Extension (Lot 1 & Lot 2)\",\"awardDate\":\"2020-09-01T00:00:00.000Z\",\"implementationPrice\":2300000,\"maintenancePricePerYear\":0,\"currencyId\":2,\"scope\":\"Chittagong VTS was delivered in 2014 with two VTS centres, four radars, nine EMCCD cameras, two AIS base stations and microwave communication system. The system was also upgraded with 10 additional CCTV cameras in 2017, and replacement of voice communication system with Tidalis TactiCall in 2020.\",\"projectType\":\"VTS\",\"products\":\"V3000\",\"description\":null,\"customerDetails\":null,\"endUserDetails\":null,\"countryId\":19,\"systemUnlocodeId\":146,\"pocName\":null,\"pocEmail\":null,\"pocPhone\":null,\"newDevelopments\":null,\"implementationDetails\":null,\"pipedriveNumber\":null,\"pipedriveUrl\":null,\"projectUrl\":null,\"isSensitive\":false,\"canBeUsedAsReference\":true,\"showOnMap\":true,\"systemDecommissioned\":false,\"deleted\":false,\"createdAt\":\"2026-09-09T20:42:34.656Z\",\"updatedAt\":\"2026-09-09T20:42:34.656Z\",\"currency\":{\"id\":2,\"code\":\"USD\",\"name\":\"US Dollar\",\"symbol\":\"$\"},\"country\":{\"id\":19,\"isoCode\":\"BD\",\"name\":\"Bangladesh\"},\"systemUnlocode\":{\"id\":146,\"code\":\"BDCGP\",\"name\":\"Chittagong\",\"countryId\":19,\"latitude\":22.3569,\"longitude\":91.7832,\"country\":{\"id\":19,\"isoCode\":\"BD\",\"name\":\"Bangladesh\"}},\"completionDates\":[],\"ports\":[],\"modules\":[],\"subSystems\":[],\"externalInterfaces\":[],\"people\":[],\"documents\":[]}',NULL,1,'dev@tidalis.com','local user','2026-09-09 20:42:34.667'),
