(292,82,NULL,'VTS Amsterdam Rhine Canal','CREATE',NULL,'{\"id\":82,\"projectNumber\":null,\"name\":\"VTS Amsterdam Rhine Canal\",\"awardDate\":\"2012-05-01T00:00:00.000Z\",\"implementationPrice\":1548665,\"maintenancePricePerYear\":0,\"currencyId\":1,\"scope\":\"VTS ARK consists of 1 traffic centre at Wijk bij Duurstede and two lock control stations being Prinses Irenesluizen and the Beatrixsluizen. The Amsterdam Rhine Channel (ARK) has dense vessel traffic. In the Utrecht area two important sectors are monitored, the harbour area Lageweide and the crossing of the channel with the Lek river.\",\"projectType\":\"VTS\",\"products\":\"MaritimeControl\",\"description\":null,\"customerDetails\":null,\"endUserDetails\":null,\"countryId\":157,\"systemUnlocodeId\":148,\"pocName\":null,\"pocEmail\":null,\"pocPhone\":null,\"newDevelopments\":null,\"implementationDetails\":null,\"pipedriveNumber\":null,\"pipedriveUrl\":null,\"projectUrl\":null,\"isSensitive\":false,\"canBeUsedAsReference\":true,\"showOnMap\":true,\"systemDecommissioned\":false,\"deleted\":false,\"createdAt\":\"2026-09-09T20:42:34.843Z\",\"updatedAt\":\"2026-09-09T20:42:34.843Z\",\"currency\":{\"id\":1,\"code\":\"EUR\",\"name\":\"Euro\",\"symbol\":\"€\"},\"country\":{\"id\":157,\"isoCode\":\"NL\",\"name\":\"Netherlands\"},\"systemUnlocode\":{\"id\":148,\"code\":\"NLWBD\",\"name\":\"Wijk bij Duurstede\",\"countryId\":157,\"latitude\":51.9747,\"longitude\":5.3639,\"country\":{\"id\":157,\"isoCode\":\"NL\",\"name\":\"Netherlands\"}},\"completionDates\":[],\"ports\":[],\"modules\":[],\"subSystems\":[],\"externalInterfaces\":[],\"people\":[],\"documents\":[]}',NULL,1,'dev@tidalis.com','local user','2026-09-09 20:42:34.854'),
