(295,85,NULL,'SLA Radar Sloehaven, The Netherlands','CREATE',NULL,'{\"id\":85,\"projectNumber\":null,\"name\":\"SLA Radar Sloehaven, The Netherlands\",\"awardDate\":\"2017-03-01T00:00:00.000Z\",\"implementationPrice\":94000,\"maintenancePricePerYear\":0,\"currencyId\":1,\"scope\":\"VTS centre to manage the harbour Sloehaven, east of Vlissingen in the Southern part of the Netherlands. The VTS centre is equipped with the standard V3000 VTMIS software. The system gets vessel information from 3 radar sensors and receives AIS from the Scheldt River Chain. The VTS system guides about 100 vessels a day through its waters\",\"projectType\":\"VTS\",\"products\":\"V3000\",\"description\":null,\"customerDetails\":null,\"endUserDetails\":null,\"countryId\":157,\"systemUnlocodeId\":138,\"pocName\":null,\"pocEmail\":null,\"pocPhone\":null,\"newDevelopments\":null,\"implementationDetails\":null,\"pipedriveNumber\":null,\"pipedriveUrl\":null,\"projectUrl\":null,\"isSensitive\":false,\"canBeUsedAsReference\":true,\"showOnMap\":true,\"systemDecommissioned\":false,\"deleted\":false,\"createdAt\":\"2026-09-09T20:42:34.912Z\",\"updatedAt\":\"2026-09-09T20:42:34.912Z\",\"currency\":{\"id\":1,\"code\":\"EUR\",\"name\":\"Euro\",\"symbol\":\"€\"},\"country\":{\"id\":157,\"isoCode\":\"NL\",\"name\":\"Netherlands\"},\"systemUnlocode\":{\"id\":138,\"code\":\"NLVLI\",\"name\":\"Vlissingen\",\"countryId\":157,\"latitude\":51.45,\"longitude\":3.7,\"country\":{\"id\":157,\"isoCode\":\"NL\",\"name\":\"Netherlands\"}},\"completionDates\":[],\"ports\":[],\"modules\":[],\"subSystems\":[],\"externalInterfaces\":[],\"people\":[],\"documents\":[]}',NULL,1,'dev@tidalis.com','local user','2026-09-09 20:42:34.924'),
(296,86,NULL,'VTS Port of Tallinn and Muuga Bay (2021)','CREATE',NULL,'{\"id\":86,\"projectNumber\":null,\"name\":\"VTS Port of Tallinn and Muuga Bay (2021)\",\"awardDate\":\"2021-12-13T00:00:00.000Z\",\"implementationPrice\":610000,\"maintenancePricePerYear\":0,\"currencyId\":1,\"scope\":\"A Vessel Traffic Services system for the Port of Tallinn and Muuga Bay.\\nThe project comprises the delivery of two X-band radar\'s, a Tracking system, Microwave Links, Multi-sensor Fusion, seven Display Positions, Consoles, Logging and replay, Control and Monitoring, a VTS Database management System, integration of Hydro/Meteo-equipment and a GPS-based central time distribution subsystem.\\nThe VTS system provides radar coverage in the port of Tallinn and Muuga Bay. A Database management System provides support to the VTS operations.\\nThe maintenance contract is effective until December 2026.\",\"projectType\":\"VTS\",\"products\":\"MaritimeControl\",\"description\":null,\"customerDetails\":null,\"endUserDetails\":null,\"countryId\":70,\"systemUnlocodeId\":150,\"pocName\":null,\"pocEmail\":null,\"pocPhone\":null,\"newDevelopments\":null,\"implementationDetails\":null,\"pipedriveNumber\":null,\"pipedriveUrl\":null,\"projectUrl\":null,\"isSensitive\":false,\"canBeUsedAsReference\":true,\"showOnMap\":true,\"systemDecommissioned\":false,\"deleted\":false,\"createdAt\":\"2026-09-09T20:42:34.936Z\",\"updatedAt\":\"2026-09-09T20:42:34.936Z\",\"currency\":{\"id\":1,\"code\":\"EUR\",\"name\":\"Euro\",\"symbol\":\"€\"},\"country\":{\"id\":70,\"isoCode\":\"EE\",\"name\":\"Estonia\"},\"systemUnlocode\":{\"id\":150,\"code\":\"EETLL\",\"name\":\"Tallinn\",\"countryId\":70,\"latitude\":59.4333,\"longitude\":24.7333,\"country\":{\"id\":70,\"isoCode\":\"EE\",\"name\":\"Estonia\"}},\"completionDates\":[],\"ports\":[],\"modules\":[],\"subSystems\":[],\"externalInterfaces\":[],\"people\":[],\"documents\":[]}',NULL,1,'dev@tidalis.com','local user','2026-09-09 20:42:34.947'),
