(317,107,NULL,'VTS Simulator NNVO','CREATE',NULL,'{\"id\":107,\"projectNumber\":null,\"name\":\"VTS Simulator NNVO\",\"awardDate\":\"2020-06-17T00:00:00.000Z\",\"implementationPrice\":1305000,\"maintenancePricePerYear\":0,\"currencyId\":1,\"scope\":\"This next level VTS Simulator provides a traffic display, shares the same technology and has been designed to able to use the same charts as an operational VTS system. A tool is available to convert existing exercises and exams and use them in the new VTS Simulator based on real mathematical representation.\",\"projectType\":\"VTS\",\"products\":\"TactiCall\",\"description\":null,\"customerDetails\":null,\"endUserDetails\":null,\"countryId\":157,\"systemUnlocodeId\":1,\"pocName\":null,\"pocEmail\":null,\"pocPhone\":null,\"newDevelopments\":null,\"implementationDetails\":null,\"pipedriveNumber\":null,\"pipedriveUrl\":null,\"projectUrl\":null,\"isSensitive\":false,\"canBeUsedAsReference\":true,\"showOnMap\":true,\"systemDecommissioned\":false,\"deleted\":false,\"createdAt\":\"2026-09-09T20:42:35.370Z\",\"updatedAt\":\"2026-09-09T20:42:35.370Z\",\"currency\":{\"id\":1,\"code\":\"EUR\",\"name\":\"Euro\",\"symbol\":\"€\"},\"country\":{\"id\":157,\"isoCode\":\"NL\",\"name\":\"Netherlands\"},\"systemUnlocode\":{\"id\":1,\"code\":\"NLRTM\",\"name\":\"Rotterdam\",\"countryId\":157,\"latitude\":51.9225,\"longitude\":4.47917,\"country\":{\"id\":157,\"isoCode\":\"NL\",\"name\":\"Netherlands\"}},\"completionDates\":[],\"ports\":[],\"modules\":[],\"subSystems\":[],\"externalInterfaces\":[],\"people\":[],\"documents\":[]}',NULL,1,'dev@tidalis.com','local user','2026-09-09 20:42:35.380'),
(318,108,NULL,'Modernisation VVZ','CREATE',NULL,'{\"id\":108,\"projectNumber\":null,\"name\":\"Modernisation VVZ\",\"awardDate\":\"2020-07-01T00:00:00.000Z\",\"implementationPrice\":240000,\"maintenancePricePerYear\":0,\"currencyId\":1,\"scope\":\"The monitoring and control of the bridges and locks along the Walcheren canal (Kanaal door Walcheren) and of the bridge passage in the ‘Zeelandbrug’ are done from the province’s control centre in Vlissingen. The monitoring along the canal are done with cameras. The monitoring around Zeelandbrug is done with radar, AIS and cameras. \\nThe system features radar and AIS processing, tracking and presentation of the traffic image. Maintenance comprises both preventive maintenance and corrective maintenance.\",\"projectType\":\"VTS\",\"products\":\"MaritimeControl\",\"description\":null,\"customerDetails\":null,\"endUserDetails\":null,\"countryId\":157,\"systemUnlocodeId\":138,\"pocName\":null,\"pocEmail\":null,\"pocPhone\":null,\"newDevelopments\":null,\"implementationDetails\":null,\"pipedriveNumber\":null,\"pipedriveUrl\":null,\"projectUrl\":null,\"isSensitive\":false,\"canBeUsedAsReference\":true,\"showOnMap\":true,\"systemDecommissioned\":false,\"deleted\":false,\"createdAt\":\"2026-09-09T20:42:35.399Z\",\"updatedAt\":\"2026-09-09T20:42:35.399Z\",\"currency\":{\"id\":1,\"code\":\"EUR\",\"name\":\"Euro\",\"symbol\":\"€\"},\"country\":{\"id\":157,\"isoCode\":\"NL\",\"name\":\"Netherlands\"},\"systemUnlocode\":{\"id\":138,\"code\":\"NLVLI\",\"name\":\"Vlissingen\",\"countryId\":157,\"latitude\":51.45,\"longitude\":3.7,\"country\":{\"id\":157,\"isoCode\":\"NL\",\"name\":\"Netherlands\"}},\"completionDates\":[],\"ports\":[],\"modules\":[],\"subSystems\":[],\"externalInterfaces\":[],\"people\":[],\"documents\":[]}',NULL,1,'dev@tidalis.com','local user','2026-09-09 20:42:35.409'),
