(347,137,NULL,'VTS for Port of Belfast','CREATE',NULL,'{\"id\":137,\"projectNumber\":null,\"name\":\"VTS for Port of Belfast\",\"awardDate\":\"2024-03-28T00:00:00.000Z\",\"implementationPrice\":2950000,\"maintenancePricePerYear\":0,\"currencyId\":1,\"scope\":\"This project replaces the existing, end-of-life, Belfast VTS system with a new system with updated sensors and additional sensor sites. The new system is based on the MaritimeControl - Service Suite Edition (MCSSE) software and will reuse the existing Tillysburn- and Blackhead sites. New sensor sites are Dorisland, Ballast Quay and Thomson Dry Dock.\",\"projectType\":\"VTS\",\"products\":\"MCSSE\",\"description\":null,\"customerDetails\":null,\"endUserDetails\":null,\"countryId\":235,\"systemUnlocodeId\":112,\"pocName\":null,\"pocEmail\":null,\"pocPhone\":null,\"newDevelopments\":null,\"implementationDetails\":null,\"pipedriveNumber\":null,\"pipedriveUrl\":null,\"projectUrl\":null,\"isSensitive\":false,\"canBeUsedAsReference\":true,\"showOnMap\":true,\"systemDecommissioned\":false,\"deleted\":false,\"createdAt\":\"2026-09-09T20:42:35.779Z\",\"updatedAt\":\"2026-09-09T20:42:35.779Z\",\"currency\":{\"id\":1,\"code\":\"EUR\",\"name\":\"Euro\",\"symbol\":\"€\"},\"country\":{\"id\":235,\"isoCode\":\"GB\",\"name\":\"United Kingdom\"},\"systemUnlocode\":{\"id\":112,\"code\":\"GBBEL\",\"name\":\"Belfast\",\"countryId\":235,\"latitude\":54.9833,\"longitude\":-5.9167,\"country\":{\"id\":235,\"isoCode\":\"GB\",\"name\":\"United Kingdom\"}},\"completionDates\":[],\"ports\":[],\"modules\":[],\"subSystems\":[],\"externalInterfaces\":[],\"people\":[],\"documents\":[]}',NULL,1,'dev@tidalis.com','local user','2026-09-09 20:42:35.785'),
