(349,139,NULL,'Dutch National AIS Network','CREATE',NULL,'{\"id\":139,\"projectNumber\":null,\"name\":\"Dutch National AIS Network\",\"awardDate\":\"2024-10-01T00:00:00.000Z\",\"implementationPrice\":7400000,\"maintenancePricePerYear\":0,\"currencyId\":1,\"scope\":\"AIS2025 is the successor to the national AIS network called DIAMONIS. The MaritimeControl Service Suite Edition software manages the data exchange of 94 existing AIS base stations, processing over 500 messages per second. The software licenses cover a single test cluster, a redundant acceptance cluster and a redundant production cluster. The software is updated every month.\",\"projectType\":\"OTHER\",\"products\":\"MCSSE\",\"description\":null,\"customerDetails\":null,\"endUserDetails\":null,\"countryId\":157,\"systemUnlocodeId\":157,\"pocName\":null,\"pocEmail\":null,\"pocPhone\":null,\"newDevelopments\":null,\"implementationDetails\":null,\"pipedriveNumber\":null,\"pipedriveUrl\":null,\"projectUrl\":null,\"isSensitive\":false,\"canBeUsedAsReference\":true,\"showOnMap\":true,\"systemDecommissioned\":false,\"deleted\":false,\"createdAt\":\"2026-09-09T20:42:35.807Z\",\"updatedAt\":\"2026-09-09T20:42:35.807Z\",\"currency\":{\"id\":1,\"code\":\"EUR\",\"name\":\"Euro\",\"symbol\":\"€\"},\"country\":{\"id\":157,\"isoCode\":\"NL\",\"name\":\"Netherlands\"},\"systemUnlocode\":{\"id\":157,\"code\":\"NLDHR\",\"name\":\"Den Helder\",\"countryId\":157,\"latitude\":52.95,\"longitude\":4.7667,\"country\":{\"id\":157,\"isoCode\":\"NL\",\"name\":\"Netherlands\"}},\"completionDates\":[],\"ports\":[],\"modules\":[],\"subSystems\":[],\"externalInterfaces\":[],\"people\":[],\"documents\":[]}',NULL,1,'dev@tidalis.com','local user','2026-09-09 20:42:35.814'),
